// Deterministic inputs for comparison with the supplied Beta.7 workbook.
// These are synthetic metrology cases; expected answers are captured from Excel,
// never generated by the JavaScript implementation under test.
import fs from 'node:fs';
const base = { nominal: 10, lowerLimit: 9, upperLimit: 11, initialGB: 1, uCal: '', mu: 0, xcal: 0,
  tur: 4, reop: .9, turNeeded: 4, originalInterval: 12, pfaTarget: .02, reopTarget: .85,
  decayModel: 'E1', weibullBeta: 2, resolution: '' };
const geometry = {
  symmetric: {}, asymmetric: { nominal: 9.6 },
  lower: { upperLimit: '' }, upper: { lowerLimit: '' },
  lowerUnknown: { nominal: '', upperLimit: '', tur: '', turNeeded: '', reop: '', reopTarget: '', uCal: .25 },
  upperUnknown: { nominal: '', lowerLimit: '', tur: '', turNeeded: '', reop: '', reopTarget: '', uCal: .25 },
};
export const cases = [];
const add = (id, shape, patch = {}) => cases.push({ id, input: { ...base, ...geometry[shape], ...patch } });
for (const shape of ['symmetric', 'asymmetric', 'lower', 'upper']) {
  for (const model of ['E1', 'E2', 'D', 'W1', 'W2']) {
    for (const [bias, mu, xcal, initialGB] of [['centered', 0, 0, 1], ['positive', .25, .1, .8], ['negative', -.25, -.1, 1]]) {
      for (const [tur, turNeeded] of [[4, 4], [1, 4], [4, 1]]) {
        for (const resolution of ['', .01, .25]) {
          add(`${shape}/${model}/${bias}/tur${tur}-ref${turNeeded}/res${resolution || 'none'}`, shape,
            { decayModel: model, mu, xcal, initialGB, tur, turNeeded, resolution });
        }
      }
    }
  }
}
// Scalar and geometry boundaries exercise both valid and impossible inputs.
for (const shape of ['symmetric', 'asymmetric', 'lower', 'upper']) {
  for (const reop of [0, .1, .499999, .5, .500001, .99, .999999999, 1]) add(`${shape}/assumed-${reop}`, shape, { reop, tur: .5, turNeeded: .5 });
  for (const reopTarget of [0, .49, .5, .500001, .999999999, 1, '']) add(`${shape}/target-${reopTarget}`, shape, { reopTarget });
  for (const pfaTarget of [0, .00001, .001, .020049, .02005, 1, '']) add(`${shape}/pfa-${pfaTarget}`, shape, { pfaTarget });
  for (const resolution of [0, -1, 3, 'invalid']) add(`${shape}/resolution-${resolution}`, shape, { resolution });
  for (const tur of [0, -1, '', 100]) add(`${shape}/tur-${tur}`, shape, { tur });
  for (const [label, patch] of Object.entries({ noReference: { turNeeded: '' }, noModel: { decayModel: '' },
    badModel: { decayModel: 'invalid' }, noInterval: { originalInterval: '' }, zeroInterval: { originalInterval: 0 },
    missingBeta: { decayModel: 'W1', weibullBeta: '' }, badBeta: { decayModel: 'W2', weibullBeta: 0 } })) add(`${shape}/${label}`, shape, patch);
}
// The one-sided normal's infinite-spread limit is 50%; include means on both
// sides of the limit and at the limit, not just conventional >50% reliability.
for (const shape of ['lower', 'upper']) {
  const sign = shape === 'lower' ? -1 : 1;
  for (const mu of [sign * .999999, sign, sign * 1.000001, sign * 1.5]) {
    for (const reop of [.1, .499999999, .5, .500000001, .9]) add(`${shape}/asymptote/mu${mu}/reop${reop}`, shape, { mu, reop });
  }
}
// Same physical limits/mean/calibration bias, different nominal origin.
for (const resolution of ['', .01, .15]) for (const initialGB of [1, .8]) {
  add(`equivalent/symmetric/${resolution}/${initialGB}`, 'symmetric', { mu: .2, xcal: .1, resolution, initialGB });
  add(`equivalent/asymmetric/${resolution}/${initialGB}`, 'asymmetric', { mu: .6, xcal: .1, resolution, initialGB });
}
for (const shape of ['lowerUnknown', 'upperUnknown']) {
  for (const pfaTarget of [.001, .02, .5, 0, 1]) for (const uCal of [.25, 0, -1]) {
    add(`${shape}/pfa${pfaTarget}/unc${uCal}`, shape, { pfaTarget, uCal });
  }
  add(`${shape}/invalid-tur`, shape, { tur: 4 });
  add(`${shape}/resolution`, shape, { resolution: .1 });
}
add('invalid/no-limits', 'symmetric', { lowerLimit: '', upperLimit: '' });
add('invalid/reversed-limits', 'symmetric', { lowerLimit: 11, upperLimit: 9 });
add('invalid/nominal-outside', 'symmetric', { nominal: 12 });
// Re-capture historical regression inputs against the current workbook rather
// than preserving outputs from the superseded Beta.4 release.
cases.push(...JSON.parse(fs.readFileSync(new URL('./risk-beta7-legacy-inputs.json', import.meta.url), 'utf8')));
add('physical/asymmetric-voltage', 'asymmetric', { nominal: 20, lowerLimit: 19, upperLimit: 25,
  tur: 2.65, reop: .85, resolution: .01 });
add('physical/pressure', 'symmetric', { nominal: 25, lowerLimit: 24.8, upperLimit: 25.2,
  tur: .2 / .063257566, reop: .85, resolution: .1 });
if (process.argv[2]) {
  fs.writeFileSync(process.argv[2], JSON.stringify(cases, null, 2));
  console.log(`Prepared ${cases.length} workbook comparison cases.`);
}
